class Card:
    def __init__(self, front, back, box=1):
        self.front = front
        self.back = back
        self.box = int(box)

    def promote(self, max_box=3):
        if self.box < max_box:
            self.box += 1

    def demote(self):
        self.box = 1

    def to_dict(self):
        return {"front": self.front, "back": self.back, "box": self.box}


