class LeitnerSystem:
    def __init__(self, deck):
        self.deck = deck

    def review_card(self, card, user_answer):
        if user_answer.strip().lower() == card.back.strip().lower():
            card.promote()
            return True
        else:
            card.demote()
            return False

    def get_summary(self):
        return {b: len(self.deck.cards_in_box(b)) for b in (1, 2, 3)}

